def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append((oid, opp))

    if not alive_opps:
        safe = DAILY_SALARY * 0.22
        if hp <= 2 or no_water_days >= 2:
            safe = DAILY_SALARY * 0.55
        return float(max(0.0, min(budget, safe)))

    highest_prev = 0.0
    cindy_prev = None
    needy_count = 0
    rich_count = 0

    for oid, opp in alive_opps:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            needy_count += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            if bid > highest_prev:
                highest_prev = bid
            if oid == 'Cindy':
                cindy_prev = bid

    units_available = supply / float(WATER_REQ)
    scarce = units_available < 1.25
    comfortable = units_available > 1.7

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if day >= 8:
        urgency += 1

    base = DAILY_SALARY * 0.24

    if comfortable:
        base = DAILY_SALARY * 0.18
    if scarce:
        base = DAILY_SALARY * 0.34

    if cindy_prev is not None:
        if cindy_prev >= 120:
            base = min(base, DAILY_SALARY * 0.2)
        elif cindy_prev >= 90:
            base = max(base, DAILY_SALARY * 0.28)
        elif cindy_prev <= 50:
            base = max(base, cindy_prev + 2.0)

    if highest_prev > 0:
        if highest_prev >= 100 and urgency <= 1:
            base = min(base, DAILY_SALARY * 0.2)
        elif highest_prev <= 35:
            base = max(base, highest_prev + 1.5)

    if needy_count >= 1 and scarce:
        base = max(base, DAILY_SALARY * 0.42)

    if urgency >= 5:
        bid = DAILY_SALARY * 0.96
    elif urgency >= 3:
        bid = max(base, DAILY_SALARY * 0.62)
    elif urgency >= 2:
        bid = max(base, DAILY_SALARY * 0.46)
    else:
        bid = base

    reserve_days = max(0, 10 - day)
    soft_cap = budget
    if reserve_days > 0:
        soft_cap = min(soft_cap, budget / float(reserve_days))
        soft_cap = max(soft_cap, DAILY_SALARY * 0.18)

    if urgency >= 3:
        soft_cap = budget

    bid = min(bid, soft_cap)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        # If no opponents are alive, bid low to save budget
        return min(my_status['budget'], DAILY_SALARY * 0.2)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If opponents were very aggressive yesterday
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                # If healthy, conserve budget
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            # If HP is low, bid aggressively to survive
            return min(my_status['budget'], DAILY_SALARY * 0.95)

        # Otherwise, bid slightly above the highest previous bid to be competitive
        # Ensure bid is at least a moderate level
        return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

    # If no yesterday_bids (e.g., Day 1 or all previous bids were None/error)
    if my_status['hp'] <= 2:
        # Aggressive bid for survival if HP is critically low
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    # Moderate default bid
    return min(my_status['budget'], DAILY_SALARY * 0.55)

